assert "not placed in a cell (the schedule was not current): 30 missing frames of 830" in out, out
assert "slot  7 retries    50   100   150" in out, out
assert "MCS10+ %    50    50    50" in out, out
assert "signal     -55   -55" in out, out
assert "MCS0-7 0, MCS8-9 -, MCS10-11 167" in out, out
print("cell detail tests ok")

split = reg(ITLAWDLCoexSeqGapSlot="<>", ITLAWDLCoexSeqGapRing="<>", ITLAWDLCoexSeqGapRingCount="3",
            ITLAWDLCoexSeqSeen="900", ITLAWDLCoexSeqMissing="100")
out = cc.analyze(split)
assert "inside the iPhone's present windows 10 (10%, 1 gaps), partly across its away slots 60 (60%, 1 gaps), fully across them 30 (30%, 1 gaps)" in out, out
assert "so about 1.0% of the frames sent were lost inside the present windows (of the 10.00% headline" in out, out
print("split tests ok")

